import express from 'express';
import cookieParser from 'cookie-parser';
import crypto from 'node:crypto';
import { pool, tx } from './db.js';
import { hash, token, uuid, payloadHash, fail } from './security.js';
import { marketReadRouter } from './market-read.js';
import { marketRecoveryRouter, beginRecovery, recordRecovery } from './market-recovery.js';
import { pagesAuthRouter, authenticatePagesBearer, sourceLimit, PAGES_ORIGIN, FIRST_PARTY_ORIGIN } from './pages-auth.js';
import { lockTradeKey, getTradeRejection, saveTradeRejection, assertNoCancelResult, getCancelResult, saveCancelResult } from './trade-rejections.js';
import { checkStartupGuard } from './startup-guard.js';

const app = express();
app.use(express.json({ limit: '32kb' }));
app.use(cookieParser());
const PORT = Number(process.env.PORT || 4317);
const LOOPBACK_ORIGINS = new Set([`http://127.0.0.1:${PORT}`, `http://localhost:${PORT}`]);
const PRIMARY_CATALOG = new Set(['crop:rice','crop:vegetables','crop:sugarcane','product:milled-rice','product:canned-food','product:sugar']);
const LEGACY_CATALOG = new Set(['wood','stone','iron']);
const CATALOG = new Set([...PRIMARY_CATALOG,...LEGACY_CATALOG]);
const ALL_CATALOG = CATALOG;
const CORS_ORIGINS = new Set(['http://127.0.0.1:4173','http://localhost:5173']);
const pagesAuthEnabled=process.env.MARKET_PAGES_AUTH_ENABLED==='true';
const configuredOrigins = String(process.env.MARKET_ALLOWED_ORIGINS || '').split(',').map(x=>x.trim()).filter(Boolean);
const ALLOWED_MUTATION_ORIGINS = new Set([...LOOPBACK_ORIGINS, ...CORS_ORIGINS, ...configuredOrigins]);
const SECURE_COOKIES = process.env.MARKET_SECURE_COOKIES === 'true';
if(pagesAuthEnabled&&(!SECURE_COOKIES||!configuredOrigins.includes(FIRST_PARTY_ORIGIN)||process.env.MARKET_PAGES_TRUSTED_PROXY!=='true'))throw new Error('Pages auth requires secure cookies, exact first-party origin and verified proxy');
const CLAIM_TIMEOUT_MS = Number(process.env.MARKET_RECEIPT_CLAIM_TIMEOUT_MS || 10 * 60 * 1000);
const MAX_PRICE = 1_000_000n, MAX_QUANTITY = 1_000_000n, MAX_TOTAL = 9_000_000_000_000_000n;
const guestCreates = new Map();
const ttl = () => new Date(Date.now() + Number(process.env.SESSION_TTL_HOURS || 24) * 3600000);
const cookieOptions = (expires) => ({ sameSite:'lax', secure:SECURE_COOKIES, path:'/', maxAge:expires-Date.now() });
app.use((req,res,next)=>{const origin=req.get('origin'),pages=pagesAuthEnabled&&origin===PAGES_ORIGIN;if(origin&&(CORS_ORIGINS.has(origin)||pages)){res.set('Access-Control-Allow-Origin',origin);res.set('Vary','Origin');if(!pages)res.set('Access-Control-Allow-Credentials','true');res.set('Access-Control-Allow-Headers',pages?'content-type,authorization,idempotency-key':'content-type,x-csrf-token,idempotency-key');res.set('Access-Control-Allow-Methods','GET,POST,OPTIONS');}if(req.method==='OPTIONS')return res.sendStatus(origin&&(CORS_ORIGINS.has(origin)||pages)?204:403);next();});
function cryptoSafeEqual(a,b){const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&crypto.timingSafeEqual(x,y);}
function parsePositiveInt(v,max){if(!Number.isSafeInteger(v)||v<=0||BigInt(v)>max)throw fail(400,'invalid positive integer');return v;}
function parseExpiry(v){const d=v?new Date(v):new Date(Date.now()+86400000);if(Number.isNaN(d.valueOf())||d<=new Date()||d>new Date(Date.now()+7*86400000))throw fail(400,'invalid expiry');return d;}
function guest(req,_res,next){(async()=>{if(pagesAuthEnabled&&req.get('authorization')){req.account=await authenticatePagesBearer(pool,req);req.authMode='pages';return next();}const raw=req.cookies.cm_guest;if(!raw)throw fail(401,'guest session required');const {rows}=await pool.query('SELECT a.*,s.csrf_hash FROM sessions s JOIN accounts a ON a.id=s.account_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now()',[hash(raw)]);if(!rows[0]||rows[0].kind!=='guest')throw fail(401,'invalid or expired guest session');req.account=rows[0];next();})().catch(next);}
function csrf(req,_res,next){const origin=req.get('origin');if(req.authMode==='pages')return origin===PAGES_ORIGIN?next():next(fail(403,'origin not allowed'));if(origin&&!ALLOWED_MUTATION_ORIGINS.has(origin))return next(fail(403,'origin not allowed'));const a=req.cookies.cm_csrf,b=req.get('x-csrf-token');if(!a||!b||a!==b||a.length>256||hash(a)!==req.account.csrf_hash)return next(fail(403,'csrf check failed'));next();}
function admin(req,_res,next){const configured=process.env.ADMIN_TOKEN,supplied=req.get('authorization')?.replace(/^Bearer /,'');if(!configured||!supplied||!cryptoSafeEqual(supplied,configured))return next(fail(403,'admin authorization required'));next();}
app.use('/v1/market',marketReadRouter({pool,guest}));
const recoveryEnabled=process.env.MARKET_RECOVERY_ENABLED==='true';
const tradeRejectionsEnabled=process.env.MARKET_TRADE_REJECTIONS_ENABLED==='true';
if(recoveryEnabled&&tradeRejectionsEnabled)throw new Error('Trade rejections and recovery require an independently reviewed combined cutover');
if(tradeRejectionsEnabled&&!pagesAuthEnabled)throw new Error('Trade rejections require the verified Pages proxy and source limiter');
const recoveryStrictCancel=recoveryEnabled&&process.env.MARKET_RECOVERY_ENFORCE_KEYED_CANCEL==='true';
if(recoveryEnabled)app.use('/v1/recovery',marketRecoveryRouter({tx,guest,csrf,strictCancel:recoveryStrictCancel}));
if(pagesAuthEnabled)app.use('/v1/pages',pagesAuthRouter({pool,tx,guest,csrf,cookieOptions,secureCookies:SECURE_COOKIES}));
app.use('/v1/op', (req,_res,next)=>{if(req.method==='POST'&&req.path.endsWith('/cancel')&&process.env.MARKET_ALLOW_DEPOSITS!=='true')return next(fail(403,'policy-disabled'));next();});
async function releaseExpired(c){const expired=await c.query("SELECT id,seller_id,item_code,quantity FROM listings WHERE status='open' AND expires_at<=now() FOR UPDATE");for(const l of expired.rows){await c.query("INSERT INTO inventories(account_id,item_code,quantity) VALUES($1,$2,$3) ON CONFLICT(account_id,item_code) DO UPDATE SET quantity=inventories.quantity+EXCLUDED.quantity",[l.seller_id,l.item_code,l.quantity]);await c.query("INSERT INTO inventory_movements(listing_id,from_account_id,to_account_id,item_code,quantity,kind) VALUES($1,NULL,$2,$3,$4,'release')",[l.id,l.seller_id,l.item_code,l.quantity]);await c.query("UPDATE listings SET status='expired',quantity=0 WHERE id=$1",[l.id]);}}

app.get('/health',(_req,res)=>res.json({ok:true,label:process.env.SANDBOX_LABEL||'CityManager Market SANDBOX',mode:'market-only',secure_cookies:SECURE_COOKIES,allowed_origin_configured:configuredOrigins.length>0,fixture_mode:process.env.SANDBOX_FIXTURE_MODE==='true',deposits_enabled:process.env.MARKET_ALLOW_DEPOSITS==='true'}));
app.get('/version',(_req,res)=>res.json({name:'citymanager-market-sandbox',version:'0.2.0',sandbox:true,contract:'market-handoff-v9-chain-4'}));
app.post('/v1/auth/guest',async(req,res,next)=>{try{if(pagesAuthEnabled)await sourceLimit(pool,req,'guest-create',10);else{const now=Date.now(),ip=req.ip,recent=(guestCreates.get(ip)||[]).filter(t=>t>now-60000);if(recent.length>=10)throw fail(429,'guest creation rate limited');guestCreates.set(ip,[...recent,now]);}const raw=token(),csrfToken=token(),id=uuid(),expires=ttl();await tx(async c=>{await c.query("INSERT INTO accounts(id,kind,expires_at) VALUES($1,'guest',$2)",[id,pagesAuthEnabled?null:expires]);await c.query('INSERT INTO wallets(account_id,balance,seq) VALUES($1,0,0)',[id]);await c.query("INSERT INTO inventories(account_id,item_code,quantity) SELECT $1,item_code,0 FROM unnest($2::text[]) item_code",[id,[...CATALOG]]);await c.query('INSERT INTO sessions(token_hash,account_id,expires_at,csrf_hash) VALUES($1,$2,$3,$4)',[hash(raw),id,expires,hash(csrfToken)]);});res.cookie('cm_guest',raw,{...cookieOptions(expires),httpOnly:true});res.cookie('cm_csrf',csrfToken,cookieOptions(expires));res.status(201).json({guest_id:id,expires_at:expires.toISOString()});}catch(e){next(e);}});
app.post('/v1/auth/logout',guest,csrf,async(req,res,next)=>{try{await pool.query('UPDATE sessions SET revoked_at=now() WHERE account_id=$1 AND revoked_at IS NULL',[req.account.id]);res.clearCookie('cm_guest');res.clearCookie('cm_csrf');res.status(204).end();}catch(e){next(e);}});
app.get('/v1/me',guest,async(req,res,next)=>{try{const w=await pool.query('SELECT balance,seq FROM wallets WHERE account_id=$1',[req.account.id]);res.json({guest_id:req.account.id,balance:w.rows[0].balance,seq:String(w.rows[0].seq)});}catch(e){next(e);}});
app.get('/v1/wallet',guest,async(req,res,next)=>{try{const w=await pool.query('SELECT balance,seq FROM wallets WHERE account_id=$1',[req.account.id]);res.json({credits:String(w.rows[0].balance),seq:String(w.rows[0].seq)});}catch(e){next(e);}});
app.get('/v1/inventory',guest,async(req,res,next)=>{try{const r=await pool.query("SELECT item_code,quantity FROM inventories WHERE account_id=$1 ORDER BY item_code",[req.account.id]);res.json({catalog:[...PRIMARY_CATALOG],items:r.rows,imports_enabled:Boolean(process.env.MARKET_ALLOW_DEPOSITS==='true')});}catch(e){next(e);}});
app.get('/v1/my/listings',guest,async(req,res,next)=>{try{const r=await pool.query('SELECT id,item_code,unit_price,quantity,status,expires_at FROM listings WHERE seller_id=$1 ORDER BY created_at DESC LIMIT 100',[req.account.id]);res.json(r.rows);}catch(e){next(e);}});
app.get('/v1/wallet/ledger',guest,async(req,res,next)=>{try{const r=await pool.query("SELECT operation_id,kind,amount,listing_id,created_at FROM ledger_entries WHERE account_id=$1 ORDER BY created_at DESC LIMIT 100",[req.account.id]);res.json(r.rows);}catch(e){next(e);}});
const isUuid=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
const depositItem=v=>typeof v==='string'&&PRIMARY_CATALOG.has(v);
// Both deposit and cancellation serialize on the same canonical operation ID,
// including when neither operation row exists yet.
const lockDepositOp=(c,opId)=>c.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',['citymanager:deposit:'+opId.toLowerCase()]);
app.post('/v1/deposits',guest,csrf,async(req,res,next)=>{try{if(process.env.MARKET_ALLOW_DEPOSITS!=='true')throw fail(403,'policy-disabled');const opId=req.body?.opId,itemId=req.body?.itemId,qty=parsePositiveInt(req.body?.qty,MAX_QUANTITY);if(!isUuid(opId)||!depositItem(itemId))throw fail(400,'invalid deposit payload');const ph=payloadHash({opId,itemId,qty});const out=await tx(async c=>{if(tradeRejectionsEnabled){await lockTradeKey(c,req.account.id,opId);await getTradeRejection(c,req.account.id,opId,'deposit',{opId,itemId,qty});await assertNoCancelResult(c,req.account.id,opId);}let recovery;if(recoveryEnabled){recovery=await beginRecovery(c,req.account.id,'deposit',opId,{opId,itemId,qty});if(recovery.current.state==='done')return recovery.current.response;}await lockDepositOp(c,opId);const cancelled=(await c.query('SELECT account_id FROM deposit_cancellations WHERE op_id=$1',[opId])).rows[0];if(cancelled){if(cancelled.account_id!==req.account.id)throw fail(409,'op-unavailable');throw fail(409,'deposit-cancelled');}const old=(await c.query('SELECT * FROM deposit_operations WHERE op_id=$1 FOR UPDATE',[opId])).rows[0];if(old){if(old.account_id!==req.account.id)throw fail(409,'op-unavailable');if(old.payload_hash!==ph)throw fail(409,'op-mismatch');return {depositId:old.op_id,itemId:old.item_code,qty:Number(old.quantity),seq:String(old.seq),state:old.state,idempotent:true};}const w=(await c.query('UPDATE wallets SET seq=seq+1 WHERE account_id=$1 RETURNING seq',[req.account.id])).rows[0];if(!w)throw fail(500,'wallet invariant unavailable');await c.query('INSERT INTO inventories(account_id,item_code,quantity) VALUES($1,$2,$3) ON CONFLICT(account_id,item_code) DO UPDATE SET quantity=inventories.quantity+EXCLUDED.quantity',[req.account.id,itemId,qty]);await c.query("INSERT INTO inventory_movements(operation_id,from_account_id,to_account_id,item_code,quantity,kind) VALUES($1,NULL,$2,$3,$4,'deposit')",[opId,req.account.id,itemId,qty]);await c.query('INSERT INTO deposit_operations(op_id,account_id,item_code,quantity,payload_hash,state,seq) VALUES($1,$2,$3,$4,$5,\'done\',$6)',[opId,req.account.id,itemId,qty,ph,w.seq]);const response={depositId:opId,itemId,qty,seq:String(w.seq),state:'done',idempotent:false};if(recovery)await recordRecovery(c,req.account.id,recovery.operation,201,response);return response;});res.status(201).json(out);}catch(e){next(e);}});
app.get('/v1/op/:opId',guest,async(req,res,next)=>{try{if(!isUuid(req.params.opId))throw fail(400,'invalid opId');const r=await pool.query('SELECT op_id,item_code,quantity,seq,state,created_at FROM deposit_operations WHERE op_id=$1 AND account_id=$2',[req.params.opId,req.account.id]);if(r.rows[0])return res.json({state:r.rows[0].state,depositId:r.rows[0].op_id,itemId:r.rows[0].item_code,qty:Number(r.rows[0].quantity),seq:String(r.rows[0].seq),created_at:r.rows[0].created_at});if((await pool.query('SELECT 1 FROM deposit_cancellations WHERE op_id=$1 AND account_id=$2',[req.params.opId,req.account.id])).rowCount)return res.json({state:'cancelled',opId:req.params.opId});res.json({state:'unknown',opId:req.params.opId});}catch(e){next(e);}});
app.post('/v1/op/:opId/cancel',guest,csrf,async(req,res,next)=>{try{if(!isUuid(req.params.opId))throw fail(400,'invalid opId');const out=await tx(async c=>{await lockDepositOp(c,req.params.opId);const old=(await c.query('SELECT account_id,state FROM deposit_operations WHERE op_id=$1 FOR UPDATE',[req.params.opId])).rows[0];if(old&&old.account_id!==req.account.id)throw fail(409,'op-unavailable');if(old?.state==='done')throw fail(409,'deposit-already-done');if(old?.state==='cancelled')return {opId:req.params.opId,state:'cancelled',idempotent:true};const prior=(await c.query('SELECT account_id FROM deposit_cancellations WHERE op_id=$1',[req.params.opId])).rows[0];if(prior){if(prior.account_id!==req.account.id)throw fail(409,'op-unavailable');return {opId:req.params.opId,state:'cancelled',idempotent:true};}await c.query('INSERT INTO deposit_cancellations(op_id,account_id) VALUES($1,$2)',[req.params.opId,req.account.id]);return {opId:req.params.opId,state:'cancelled',idempotent:false};});res.json(out);}catch(e){next(e);}});
app.get('/v1/receipts',guest,async(req,res,next)=>{try{const state=req.query.state,r=await pool.query("SELECT d.operation_id AS receipt_id,d.operation_id,d.item_code,d.quantity,d.delivered_at,d.acknowledged_at,d.claim_id,d.claimed_at,d.claim_expires_at,p.total,p.listing_id,CASE WHEN d.acknowledged_at IS NOT NULL THEN 'delivered' WHEN d.claim_id IS NOT NULL AND d.claim_expires_at<now() THEN 'claim-timeout' WHEN d.claim_id IS NOT NULL THEN 'claimed' ELSE 'ready' END AS state FROM delivery_receipts d JOIN purchases p ON p.operation_id=d.operation_id WHERE d.buyer_id=$1 AND ($2::text IS NULL OR CASE WHEN d.acknowledged_at IS NOT NULL THEN 'delivered' WHEN d.claim_id IS NOT NULL AND d.claim_expires_at<now() THEN 'claim-timeout' WHEN d.claim_id IS NOT NULL THEN 'claimed' ELSE 'ready' END=$2) ORDER BY d.delivered_at DESC LIMIT 100",[req.account.id,state||null]);res.json(r.rows);}catch(e){next(e);}});
app.post('/v1/receipts/:receiptId/claim',guest,csrf,async(req,res,next)=>{try{const claimId=req.body?.claimId;if(!isUuid(req.params.receiptId)||!isUuid(claimId))throw fail(400,'invalid claimId');const out=await tx(async c=>{const r=(await c.query('SELECT * FROM delivery_receipts WHERE operation_id=$1 AND buyer_id=$2 FOR UPDATE',[req.params.receiptId,req.account.id])).rows[0];if(!r)throw fail(404,'receipt not found');if(r.acknowledged_at)throw fail(409,'already-delivered');if(r.claim_id&&String(r.claim_id)!==claimId){if(r.claim_expires_at&&new Date(r.claim_expires_at)<new Date()){await c.query("INSERT INTO receipt_claim_history(receipt_id,claim_id,action,details) VALUES($1,$2,'timeout',$3)",[r.operation_id,r.claim_id,JSON.stringify({reason:'claim-expired',reconciliation_required:true})]);}throw fail(409,'claim-reconciliation-required');}if(r.claim_id)return {receipt_id:r.operation_id,claim_id:r.claim_id,state:'claimed',claim_expires_at:r.claim_expires_at,idempotent:true};const exp=new Date(Date.now()+CLAIM_TIMEOUT_MS);await c.query('UPDATE delivery_receipts SET claim_id=$1,claimed_at=now(),claim_expires_at=$2 WHERE operation_id=$3',[claimId,exp,r.operation_id]);await c.query("INSERT INTO receipt_claim_history(receipt_id,claim_id,action,details) VALUES($1,$2,'claim','{}')",[r.operation_id,claimId]);return {receipt_id:r.operation_id,claim_id:claimId,state:'claimed',claim_expires_at:exp.toISOString(),idempotent:false};});res.json(out);}catch(e){next(e);}});
app.post('/v1/receipts/:operationId/retry',guest,async(req,res,next)=>{try{const r=await pool.query("SELECT d.operation_id,d.item_code,d.quantity,d.delivered_at,d.acknowledged_at,p.total,p.listing_id FROM delivery_receipts d JOIN purchases p ON p.operation_id=d.operation_id WHERE d.buyer_id=$1 AND d.operation_id=$2",[req.account.id,req.params.operationId]);if(!r.rows[0])throw fail(404,'receipt not found');res.json({...r.rows[0],retry_safe:true});}catch(e){next(e);}});
app.post('/v1/sandbox/fixture',guest,csrf,async(req,res,next)=>{try{if(process.env.SANDBOX_FIXTURE_MODE!=='true')throw fail(404,'sandbox fixture mode disabled');const version=req.body?.fixture_version||'fixture-v1';if(version!=='fixture-v1')throw fail(400,'unknown fixture version');const out=await tx(async c=>{const grant=await c.query('INSERT INTO sandbox_fixture_grants(account_id,fixture_version) VALUES($1,$2) ON CONFLICT(account_id) DO NOTHING RETURNING account_id',[req.account.id,version]);if(grant.rowCount===0){const w=await c.query('SELECT balance FROM wallets WHERE account_id=$1',[req.account.id]);const i=await c.query("SELECT quantity FROM inventories WHERE account_id=$1 AND item_code='wood'",[req.account.id]);return {balance:w.rows[0].balance,wood:i.rows[0].quantity,source:'sandbox-fixture',fixture_version:version,idempotent:true};}const w=await c.query('UPDATE wallets SET balance=balance+1000 WHERE account_id=$1 RETURNING balance',[req.account.id]);const i=await c.query("UPDATE inventories SET quantity=quantity+10 WHERE account_id=$1 AND item_code='wood' RETURNING quantity",[req.account.id]);if(w.rowCount!==1||i.rowCount!==1)throw fail(500,'fixture invariant unavailable');await c.query('INSERT INTO audit_events(actor_id,action,details) VALUES($1,$2,$3)',[req.account.id,'sandbox_fixture_grant',JSON.stringify({credits:1000,wood:10,fixture_version:version})]);return {balance:w.rows[0].balance,wood:i.rows[0].quantity,source:'sandbox-fixture',fixture_version:version,idempotent:false};});res.json(out);}catch(e){next(e);}});
app.post('/v1/listings',guest,csrf,async(req,res,next)=>{try{const {item_code}=req.body,unit_price=parsePositiveInt(req.body.unit_price,MAX_PRICE),quantity=parsePositiveInt(req.body.quantity,MAX_QUANTITY),expires=tradeRejectionsEnabled?null:parseExpiry(req.body.expires_at),key=req.get('idempotency-key');if(!key||key.length>128)throw fail(400,'Idempotency-Key required');if(typeof item_code!=='string'||!CATALOG.has(item_code))throw fail(400,'item not allowed');if(BigInt(unit_price)*BigInt(quantity)>MAX_TOTAL)throw fail(400,'listing total too large');if(tradeRejectionsEnabled)await sourceLimit(pool,req,'trade-list',60);const body={item_code,unit_price,quantity,expires_at:req.body.expires_at||null},ph=payloadHash(body);const out=await tx(async c=>{if(tradeRejectionsEnabled){await lockTradeKey(c,req.account.id,key);const rejected=await getTradeRejection(c,req.account.id,key,'listing',body);if(rejected)return {__tradeRejection:rejected};await assertNoCancelResult(c,req.account.id,key);}const reject=async reason=>{if(!tradeRejectionsEnabled)throw fail(409,reason);return {__tradeRejection:await saveTradeRejection(c,req.account.id,key,'listing',body,reason)};};let recovery;if(recoveryEnabled){recovery=await beginRecovery(c,req.account.id,'listing',key,body);if(recovery.current.state==='done')return recovery.current.response;}const existing=await c.query('SELECT payload_hash,response FROM idempotency_keys WHERE account_id=$1 AND key=$2 FOR UPDATE',[req.account.id,key]);if(existing.rows[0]){if(existing.rows[0].payload_hash!==ph)throw fail(409,'idempotency key payload mismatch');return existing.rows[0].response;}const expiry=tradeRejectionsEnabled?parseExpiry(req.body.expires_at):expires;const inv=await c.query('SELECT quantity FROM inventories WHERE account_id=$1 AND item_code=$2 FOR UPDATE',[req.account.id,item_code]);if(!inv.rows[0]||BigInt(inv.rows[0].quantity)<BigInt(quantity))return reject('insufficient inventory');if((await c.query('UPDATE inventories SET quantity=quantity-$1 WHERE account_id=$2 AND item_code=$3 AND quantity>=$1',[quantity,req.account.id,item_code])).rowCount!==1)throw fail(409,'insufficient inventory');const id=uuid();await c.query("INSERT INTO listings(id,seller_id,item_code,unit_price,quantity,status,expires_at) VALUES($1,$2,$3,$4,$5,'open',$6)",[id,req.account.id,item_code,unit_price,quantity,expiry]);await c.query("INSERT INTO inventory_movements(listing_id,from_account_id,to_account_id,item_code,quantity,kind) VALUES($1,$2,NULL,$3,$4,'reserve')",[id,req.account.id,item_code,quantity]);const response={id,item_code,unit_price,quantity,status:'open',expires_at:expiry.toISOString()};await c.query('INSERT INTO idempotency_keys(account_id,key,payload_hash,operation_id,response) VALUES($1,$2,$3,$4,$5)',[req.account.id,key,ph,id,response]);if(recovery)await recordRecovery(c,req.account.id,recovery.operation,201,response);return response;});res.status(out.__tradeRejection?409:201).json(out.__tradeRejection||out);}catch(e){next(e);}});
app.get('/v1/listings',guest,async(req,res,next)=>{try{await tx(releaseExpired);const r=await pool.query("SELECT id,item_code,unit_price,quantity,status,expires_at FROM listings WHERE status='open' AND expires_at>now() AND seller_id<>$1 ORDER BY created_at DESC LIMIT 200",[req.account.id]);res.json(r.rows);}catch(e){next(e);}});
app.post('/v1/listings/:id/cancel',guest,csrf,async(req,res,next)=>{try{const key=req.get('idempotency-key');if(recoveryStrictCancel&&!key)throw fail(400,'Idempotency-Key required');if((recoveryEnabled||tradeRejectionsEnabled)&&key&&key.length>128)throw fail(400,'invalid operation key');if(tradeRejectionsEnabled&&key)await sourceLimit(pool,req,'trade-cancel',60);const payload={listing_id:req.params.id},guarded=Boolean(tradeRejectionsEnabled&&key);const out=await tx(async c=>{if(guarded){await lockTradeKey(c,req.account.id,key);const rejected=await getTradeRejection(c,req.account.id,key,'cancel',payload);if(rejected)return {__tradeRejection:rejected};const prior=await getCancelResult(c,req.account.id,key,payload);if(prior)return prior;}const reject=async reason=>{if(!guarded)throw fail(reason==='listing not found'?404:409,reason);return {__tradeRejection:await saveTradeRejection(c,req.account.id,key,'cancel',payload,reason)};};let recovery;if(recoveryEnabled&&key){recovery=await beginRecovery(c,req.account.id,'cancel',key,{listing_id:req.params.id});if(recovery.current.state==='done')return recovery.current.response;}const x=await c.query('SELECT * FROM listings WHERE id=$1 FOR UPDATE',[req.params.id]);if(!x.rows[0]||x.rows[0].seller_id!==req.account.id)return reject('listing not found');if(x.rows[0].status==='cancelled'){const response=x.rows[0].cancel_response||{id:req.params.id,status:'cancelled',returned_quantity:0};if(recovery)await recordRecovery(c,req.account.id,recovery.operation,200,response);if(guarded)await saveCancelResult(c,req.account.id,key,payload,response);return response;}if(x.rows[0].status!=='open')return reject('listing not open');const response={id:req.params.id,status:'cancelled',returned_quantity:Number(x.rows[0].quantity)};await c.query("INSERT INTO inventories(account_id,item_code,quantity) VALUES($1,$2,$3) ON CONFLICT(account_id,item_code) DO UPDATE SET quantity=inventories.quantity+EXCLUDED.quantity",[req.account.id,x.rows[0].item_code,x.rows[0].quantity]);await c.query("INSERT INTO inventory_movements(listing_id,from_account_id,to_account_id,item_code,quantity,kind) VALUES($1,NULL,$2,$3,$4,'release')",[req.params.id,req.account.id,x.rows[0].item_code,x.rows[0].quantity]);await c.query("UPDATE listings SET status='cancelled',quantity=0,cancel_response=$2 WHERE id=$1",[req.params.id,response]);if(recovery)await recordRecovery(c,req.account.id,recovery.operation,200,response);if(guarded)await saveCancelResult(c,req.account.id,key,payload,response);return response;});res.status(out.__tradeRejection?409:200).json(out.__tradeRejection||out);}catch(e){next(e);}});
app.post('/v1/listings/:id/buy',guest,csrf,async(req,res,next)=>{try{const body={listing_id:req.params.id,quantity:parsePositiveInt(req.body.quantity,MAX_QUANTITY)},key=req.get('idempotency-key');if(!key||key.length>128)throw fail(400,'Idempotency-Key required');if(tradeRejectionsEnabled)await sourceLimit(pool,req,'trade-buy',60);const out=await tx(async c=>{if(tradeRejectionsEnabled){await lockTradeKey(c,req.account.id,key);const rejected=await getTradeRejection(c,req.account.id,key,'buy',body);if(rejected)return {__tradeRejection:rejected};await assertNoCancelResult(c,req.account.id,key);}const reject=async reason=>{if(!tradeRejectionsEnabled)throw fail(409,reason);return {__tradeRejection:await saveTradeRejection(c,req.account.id,key,'buy',body,reason)};};let recovery;if(recoveryEnabled){recovery=await beginRecovery(c,req.account.id,'buy',key,body);if(recovery.current.state==='done')return recovery.current.response;}const existing=await c.query('SELECT payload_hash,response FROM idempotency_keys WHERE account_id=$1 AND key=$2 FOR UPDATE',[req.account.id,key]);if(existing.rows[0]){if(existing.rows[0].payload_hash!==payloadHash(body))throw fail(409,'idempotency key payload mismatch');return existing.rows[0].response;}const l=await c.query("SELECT * FROM listings WHERE id=$1 FOR UPDATE",[req.params.id]);if(!l.rows[0]||l.rows[0].status!=='open'||new Date(l.rows[0].expires_at)<=new Date())return reject('listing unavailable');const x=l.rows[0];if(x.seller_id===req.account.id)return reject('cannot buy own listing');if(BigInt(x.quantity)<BigInt(body.quantity))return reject('insufficient stock');const total=BigInt(x.unit_price)*BigInt(body.quantity);if(total>MAX_TOTAL)throw fail(400,'purchase total too large');const ids=[req.account.id,x.seller_id].sort(),wallets=await c.query('SELECT account_id,balance FROM wallets WHERE account_id=ANY($1::uuid[]) ORDER BY account_id FOR UPDATE',[ids]);if(wallets.rowCount!==2)throw fail(500,'wallet invariant unavailable');const buyer=wallets.rows.find(w=>w.account_id===req.account.id);if(!buyer||BigInt(buyer.balance)<total)return reject('insufficient wallet');const op=uuid();if((await c.query('UPDATE wallets SET balance=balance-$1 WHERE account_id=$2 AND balance>=$1',[total.toString(),req.account.id])).rowCount!==1)throw fail(409,'insufficient wallet');if((await c.query('UPDATE wallets SET balance=balance+$1 WHERE account_id=$2',[total.toString(),x.seller_id])).rowCount!==1)throw fail(500,'wallet invariant unavailable');if((await c.query("UPDATE listings SET quantity=quantity-$1,status=CASE WHEN quantity-$1=0 THEN 'sold_out' ELSE status END WHERE id=$2 AND status='open' AND quantity>=$1",[body.quantity,req.params.id])).rowCount!==1)throw fail(409,'listing unavailable');await c.query('INSERT INTO ledger_entries(operation_id,account_id,kind,amount,listing_id) VALUES($1,$2,\'debit\',$3,$4),($1,$5,\'credit\',$3,$4)',[op,req.account.id,total.toString(),req.params.id,x.seller_id]);await c.query('INSERT INTO purchases(operation_id,listing_id,buyer_id,seller_id,quantity,unit_price,total) VALUES($1,$2,$3,$4,$5,$6,$7)',[op,req.params.id,req.account.id,x.seller_id,body.quantity,x.unit_price,total.toString()]);await c.query('INSERT INTO delivery_receipts(operation_id,buyer_id,item_code,quantity) VALUES($1,$2,$3,$4)',[op,req.account.id,x.item_code,body.quantity]);const response={operation_id:op,listing_id:req.params.id,item_code:x.item_code,quantity:body.quantity,total:total.toString(),receipt_status:'ready'};await c.query('INSERT INTO idempotency_keys(account_id,key,payload_hash,operation_id,response) VALUES($1,$2,$3,$4,$5)',[req.account.id,key,payloadHash(body),op,response]);if(recovery)await recordRecovery(c,req.account.id,recovery.operation,201,response);return response;});res.status(out.__tradeRejection?409:201).json(out.__tradeRejection||out);}catch(e){next(e);}});
app.post('/v1/receipts/:operationId/ack',guest,csrf,async(req,res,next)=>{try{const claimId=req.body?.claimId;if(!isUuid(claimId))throw fail(400,'claim-id-required');const out=await tx(async c=>{const r=(await c.query('SELECT * FROM delivery_receipts WHERE operation_id=$1 AND buyer_id=$2 FOR UPDATE',[req.params.operationId,req.account.id])).rows[0];if(!r)throw fail(404,'receipt not found');if(r.claim_id&&String(r.claim_id)!==claimId)throw fail(409,'claim-mismatch');if(!r.claim_id)throw fail(409,'claim-required');if(r.acknowledged_at)return {receipt_id:r.operation_id,claim_id:r.claim_id,state:'delivered',acknowledged_at:r.acknowledged_at,idempotent:true};const a=(await c.query('UPDATE delivery_receipts SET acknowledged_at=COALESCE(acknowledged_at,now()) WHERE operation_id=$1 RETURNING acknowledged_at',[r.operation_id])).rows[0];await c.query("INSERT INTO receipt_claim_history(receipt_id,claim_id,action,details) VALUES($1,$2,'ack','{}')",[r.operation_id,claimId]);return {receipt_id:r.operation_id,claim_id:r.claim_id,state:'delivered',acknowledged_at:a.acknowledged_at,idempotent:false};});res.json(out);}catch(e){next(e);}});
app.get('/admin',(_req,res)=>res.type('html').send(ADMIN_HTML));
