const playerHtml=()=>PLAYER_HTML_V2.replace("if(p.guest_id&&p.guest_id!==m.guest_id)","if(typeof p.guest_id!=='string'||p.guest_id!==m.guest_id)").replace("$('msg').replaceChildren(document.createTextNode('Unresolved purchase response. '),b)","$('offline').hidden=false;$('offline').replaceChildren(document.createTextNode('Unresolved purchase response. '),b)").replace("api('/v1/listings',{method:'POST',body:JSON.stringify({item_code:'wood',unit_price:25,quantity:1})})","api('/v1/listings',{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify({item_code:'wood',unit_price:25,quantity:1})})");
