app.get('/v1/admin/overview',admin,async(_req,res,next)=>{try{const [a,l,p,e]=await Promise.all([pool.query("SELECT count(*)::int count FROM accounts WHERE kind='guest'"),pool.query('SELECT status,count(*)::int count FROM listings GROUP BY status'),pool.query('SELECT count(*)::int count FROM purchases'),pool.query('SELECT count(*)::int count FROM audit_events')]);res.json({sandbox:true,guests:a.rows[0].count,listings:l.rows,purchases:p.rows[0].count,audit_events:e.rows[0].count});}catch(e){next(e);}});
