app.post('/v1/admin/listings/:id/cancel',admin,async(req,res,next)=>{try{const out=await tx(async c=>{const x=await c.query('SELECT * FROM listings WHERE id=$1 FOR UPDATE',[req.params.id]);if(!x.rows[0])throw fail(404,'listing not found');if(x.rows[0].status!=='open')throw fail(409,'listing not open');await c.query("INSERT INTO inventories(account_id,item_code,quantity) VALUES($1,$2,$3) ON CONFLICT(account_id,item_code) DO UPDATE SET quantity=inventories.quantity+EXCLUDED.quantity",[x.rows[0].seller_id,x.rows[0].item_code,x.rows[0].quantity]);await c.query("UPDATE listings SET status='cancelled',quantity=0 WHERE id=$1",[req.params.id]);await c.query('INSERT INTO audit_events(action,target_id,details) VALUES($1,$2,$3)',['admin_cancel_listing',req.params.id,JSON.stringify({reason:req.body?.reason||'admin action'})]);return {id:req.params.id,status:'cancelled'};});res.json(out);}catch(e){next(e);}});
app.use((err,_req,res,_next)=>{const status=err.status||500;if(status>=500)console.error('market request failed',{status,code:err.code||'internal'});res.status(status).json({error:status>=500?'internal error':err.message||'request failed'});});
