const ADMIN_HTML=`<!doctype html><meta charset=utf-8><title>CityManager Market SANDBOX Admin</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;background:#f7f7f4;color:#202020}main{background:white;padding:24px;border:1px solid #ddd;border-radius:12px}button{padding:8px 14px}pre{background:#111;color:#b7f7c0;padding:16px;overflow:auto}table{border-collapse:collapse;width:100%;margin-top:18px}td,th{border-bottom:1px solid #ddd;padding:6px;text-align:left}</style><main><h1>CityManager Market — SANDBOX</h1><p>Admin controls are server-authorized and isolated from guest sessions.</p><input id=t type=password placeholder="local admin token" size=42> <button id=load>Load status</button><pre id=o>Authorization required.</pre><table id=ls></table><script>const tokenInput=document.getElementById('t'),out=document.getElementById('o'),table=document.getElementById('ls');async function load(){const h={Authorization:'Bearer '+tokenInput.value};const r=await fetch('/v1/admin/overview',{headers:h});if(r.status===401||r.status===403){out.textContent='Authorization denied.';table.replaceChildren();return}if(!r.ok){out.textContent='Admin service unavailable.';table.replaceChildren();return}out.textContent=JSON.stringify(await r.json(),null,2);const q=await fetch('/v1/admin/listings',{headers:h});if(!q.ok){table.replaceChildren();return}const x=await q.json();table.replaceChildren();const head=document.createElement('tr');for(const s of ['Item','Qty','Status','']){const cell=document.createElement('th');cell.textContent=s;head.append(cell)}table.append(head);for(const a of x){const row=document.createElement('tr');for(const s of [a.item_code,a.quantity,a.status]){const cell=document.createElement('td');cell.textContent=String(s);row.append(cell)}const cell=document.createElement('td');if(a.status==='open'){const b=document.createElement('button');b.textContent='Cancel';b.onclick=()=>cancel(a.id);cell.append(b)}row.append(cell);table.append(row)}}async function cancel(id){await fetch('/v1/admin/listings/'+encodeURIComponent(id)+'/cancel',{method:'POST',headers:{Authorization:'Bearer '+tokenInput.value,'Content-Type':'application/json'},body:JSON.stringify({reason:'sandbox admin action'})});load()}document.getElementById('load').onclick=load;</script></main>`;
const MARKET_HTML=`<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>CityManager Market SANDBOX</title><style>:root{color-scheme:light}body{margin:0;font:16px system-ui;background:#eef3f1;color:#17332f}header{background:#17332f;color:#fff;padding:18px 5vw}main{max-width:1100px;margin:24px auto;padding:0 16px}.banner{background:#fff5cf;border:1px solid #e2c96b;border-radius:12px;padding:12px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.card{background:#fff;border:1px solid #d7e1de;border-radius:14px;padding:16px;box-shadow:0 2px 8px #17332f12}button{border:0;border-radius:8px;background:#236b5b;color:#fff;padding:9px 13px;cursor:pointer}button.secondary{background:#71827d}input{padding:8px;border:1px solid #b8c9c4;border-radius:7px;width:80px}.muted{color:#64756f}.error{color:#a32828}.ok{color:#236b5b}ul{padding-left:20px}</style><header><strong>CityManager Market — SANDBOX</strong><span id=who></span></header><main><div class=banner>This is a local test market. Credits and wood are fake fixtures. Real city saves, deposits, withdrawals, payments, and production claims are disabled.</div><div id=offline class="banner error" hidden>Offline: actions are paused. Reconnect and retry pending requests.</div><section id=login class=card><h2>Guest access</h2><p>Resume this browser's guest session or create a new isolated guest ID.</p><button id=enter>Enter sandbox as guest</button><p id=loginmsg class=muted></p></section><section id=app hidden><div class=grid><article class=card><h2>Wallet & fake stock</h2><p id=wallet></p><p id=stock></p><button class=secondary id=fixture>Seed fake fixture</button><p id=fixturemsg class=muted></p></article><article class=card><h2>Pending delivery</h2><ul id=receipts></ul></article><article class=card><h2>My listings</h2><ul id=mine></ul></article></div><article class=card style="margin-top:16px"><h2>Market listings</h2><div id=listings class=grid></div></article><article class=card style="margin-top:16px"><h2>Wallet history</h2><ul id=ledger></ul></article></section></main><script>const $=id=>document.getElementById(id),pendingKey='cm_market_pending';let state={jar:null};function cookie(name){return document.cookie.split('; ').find(x=>x.startsWith(name+'='))?.slice(name.length+1)||''}async function api(path,opt={}){const h={...(opt.headers||{})};if(opt.method&&opt.method!=='GET'){h['x-csrf-token']=cookie('cm_csrf');h['content-type']='application/json'}const r=await fetch(path,{...opt,headers:h});let body=null;try{body=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(body?.error||'Request failed'),{status:r.status});return body}function showError(e){$('loginmsg').textContent=e.message+(e.status?' ('+e.status+')':'');$('loginmsg').className='error'}async function enter(){try{await api('/v1/me');}catch(e){if(e.status===401){await api('/v1/auth/guest',{method:'POST',body:'{}'})}else throw e}$('login').hidden=true;$('app').hidden=false;await refresh()}async function refresh(){try{const [me,inv,ls,mine,rec,ledger]=await Promise.all([api('/v1/me'),api('/v1/inventory'),api('/v1/listings'),api('/v1/my/listings'),api('/v1/receipts'),api('/v1/wallet/ledger')]);$('who').textContent=' · Guest '+me.guest_id.slice(0,8);$('wallet').textContent='Credits: '+me.balance;$('stock').textContent='Fake stock: '+inv.items.map(x=>x.item_code+' '+x.quantity).join(', ');$('listings').replaceChildren(...ls.map(x=>{const a=document.createElement('div');a.className='card';const q=document.createElement('input');q.type='number';q.min=1;q.max=x.quantity;q.value=1;const b=document.createElement('button');b.textContent='Buy';b.onclick=()=>buy(x,q.value);const p=document.createElement('p');p.textContent=x.item_code+' · '+x.unit_price+' credits · '+x.quantity+' available';a.append(p,q,b);return a}));$('mine').replaceChildren(...mine.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+x.status;if(x.status==='open'){const b=document.createElement('button');b.textContent='Cancel';b.className='secondary';b.onclick=()=>cancel(x.id);li.append(' ',b)}return li}));$('receipts').replaceChildren(...rec.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+(x.acknowledged_at?'acknowledged':'ready');if(!x.acknowledged_at){const b=document.createElement('button');b.textContent='Retry delivery';b.onclick=()=>retry(x.operation_id);li.append(' ',b)}return li}));$('ledger').replaceChildren(...ledger.map(x=>{const li=document.createElement('li');li.textContent=x.kind+' '+x.amount+' credits · '+new Date(x.created_at).toLocaleString();return li}));}catch(e){if(!navigator.onLine)$('offline').hidden=false;showError(e)}}async function buy(x,quantity){const key=crypto.randomUUID();const p={listing:x.id,quantity,key};localStorage.setItem(pendingKey,JSON.stringify(p));try{const r=await api('/v1/listings/'+x.id+'/buy',{method:'POST',headers:{'idempotency-key':key},body:JSON.stringify({quantity:Number(quantity)})});localStorage.removeItem(pendingKey);await api('/v1/receipts/'+r.operation_id+'/ack',{method:'POST'});await refresh()}catch(e){$('fixturemsg').textContent='Buy pending: '+e.message+'. Retry after reconnect.';$('fixturemsg').className='error'}}async function retry(op){try{await api('/v1/receipts/'+op+'/retry',{method:'POST'});await api('/v1/receipts/'+op+'/ack',{method:'POST'});await refresh()}catch(e){showError(e)}}async function cancel(id){try{await api('/v1/listings/'+id+'/cancel',{method:'POST'});await refresh()}catch(e){showError(e)}}$('enter').onclick=()=>enter().catch(showError);$('fixture').onclick=()=>api('/v1/sandbox/fixture',{method:'POST'}).then(refresh).catch(showError);addEventListener('offline',()=>{$('offline').hidden=false});addEventListener('online',()=>{$('offline').hidden=true;refresh()});enter().catch(()=>{});</script>`;
const PLAYER_HTML=`<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Market player sandbox</title><style>body{font:16px system-ui;margin:0;background:#eef3f1;color:#17332f}header{background:#17332f;color:white;padding:18px 6vw}main{max-width:900px;margin:20px auto;padding:0 14px}.notice,.card{background:#fff;border:1px solid #d7e1de;border-radius:14px;padding:16px;margin:12px 0}.notice{background:#fff5cf}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.card{margin:0}button{background:#236b5b;color:#fff;border:0;border-radius:8px;padding:9px 12px;margin:4px 2px}button.alt{background:#71827d}input{width:70px;padding:8px}.muted{color:#64756f}.error{color:#a32828}</style><header><b>CityManager Market · SANDBOX</b><span id=guest></span></header><main><div class=notice>This UI uses fake credits and the explicit fake catalog wood/stone/iron. Real saves, city deposits/withdrawals, payments, and production claims are disabled.</div><div id=offline class="notice error" hidden>Offline. Market mutations are paused; reconnect to retry.</div><section id=login class=card><h2>Guest entry</h2><p>Use a browser-local guest session. No registration, email, or password.</p><button id=enter>Enter as guest</button><p id=msg class=muted></p></section><section id=app hidden><div class=grid><div class=card><h2>Wallet</h2><p id=wallet></p><p id=inv></p><button id=seed class=alt>Seed fake fixture</button><button id=list>List 1 fake wood</button></div><div class=card><h2>Receipts</h2><ul id=receipts></ul></div><div class=card><h2>My listings</h2><ul id=mine></ul></div></div><div class=card><h2>Buy from players</h2><div id=listings class=grid></div></div><div class=card><h2>Wallet history</h2><ul id=ledger></ul></div></section></main><script>const $=x=>document.getElementById(x),cookie=n=>document.cookie.split('; ').find(x=>x.startsWith(n+'='))?.slice(n.length+1)||'';async function api(p,o={}){const h={...(o.headers||{})};if(o.method&&o.method!=='GET'){h['x-csrf-token']=cookie('cm_csrf');h['content-type']='application/json'}const r=await fetch(p,{...o,headers:h});let b=null;try{b=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(b?.error||'Request failed'),{status:r.status});return b}async function guest(){try{return await api('/v1/me')}catch(e){if(e.status===401)return api('/v1/auth/guest',{method:'POST',body:'{}'});throw e}}async function refresh(){try{const [m,i,l,my,r,w]=await Promise.all([api('/v1/me'),api('/v1/inventory'),api('/v1/listings'),api('/v1/my/listings'),api('/v1/receipts'),api('/v1/wallet/ledger')]);$('guest').textContent=' · '+m.guest_id.slice(0,8);$('wallet').textContent='Credits: '+m.balance;$('inv').textContent='Fake stock: '+i.items.map(x=>x.item_code+' '+x.quantity).join(', ');$('listings').replaceChildren(...l.map(x=>{const d=document.createElement('div');d.className='card';const p=document.createElement('p');p.textContent=x.item_code+' · '+x.unit_price+' credits · '+x.quantity+' available';const q=document.createElement('input');q.type='number';q.min=1;q.max=x.quantity;q.value=1;const b=document.createElement('button');b.textContent='Buy';b.onclick=()=>buy(x.id,Number(q.value));d.append(p,q,b);return d}));$('mine').replaceChildren(...my.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+x.status;if(x.status==='open'){const b=document.createElement('button');b.textContent='Cancel';b.className='alt';b.onclick=()=>cancel(x.id);li.append(' ',b)}return li}));$('receipts').replaceChildren(...r.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+(x.acknowledged_at?'acknowledged':'pending');if(!x.acknowledged_at){const b=document.createElement('button');b.textContent='Retry';b.onclick=()=>retry(x.operation_id);li.append(' ',b)}return li}));$('ledger').replaceChildren(...w.map(x=>{const li=document.createElement('li');li.textContent=x.kind+' '+x.amount+' credits';return li}))}catch(e){$('msg').textContent=e.message;$('msg').className='error';if(!navigator.onLine)$('offline').hidden=false}}async function buy(id,q){const key=crypto.randomUUID();localStorage.setItem('market.pending',JSON.stringify({id,q,key}));try{const r=await api('/v1/listings/'+id+'/buy',{method:'POST',headers:{'idempotency-key':key},body:JSON.stringify({quantity:q})});localStorage.removeItem('market.pending');await api('/v1/receipts/'+r.operation_id+'/ack',{method:'POST'});refresh()}catch(e){$('msg').textContent='Buy pending; reconnect and retry with the same idempotency key. '+e.message;$('msg').className='error'}}async function retry(op){try{await api('/v1/receipts/'+op+'/retry',{method:'POST'});await api('/v1/receipts/'+op+'/ack',{method:'POST'});refresh()}catch(e){$('msg').textContent=e.message;$('msg').className='error'}}async function cancel(id){try{await api('/v1/listings/'+id+'/cancel',{method:'POST'});refresh()}catch(e){$('msg').textContent=e.message;$('msg').className='error'}}$('enter').onclick=async()=>{try{await guest();$('login').hidden=true;$('app').hidden=false;refresh()}catch(e){$('msg').textContent=e.message;$('msg').className='error'}};$('seed').onclick=()=>api('/v1/sandbox/fixture',{method:'POST'}).then(refresh).catch(e=>$('msg').textContent=e.message);$('list').onclick=()=>api('/v1/listings',{method:'POST',body:JSON.stringify({item_code:'wood',unit_price:25,quantity:1})}).then(refresh).catch(e=>$('msg').textContent=e.message);addEventListener('offline',()=>$('offline').hidden=false);addEventListener('online',()=>{$('offline').hidden=true;refresh()});</script>`;
const PLAYER_HTML_V2=`<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Market player sandbox</title><style>body{font:16px system-ui;margin:0;background:#eef3f1;color:#17332f}header{background:#17332f;color:#fff;padding:18px 6vw}main{max-width:900px;margin:20px auto;padding:0 14px}.notice,.card{background:#fff;border:1px solid #d7e1de;border-radius:14px;padding:16px;margin:12px 0}.notice{background:#fff5cf}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.card{margin:0}button{background:#236b5b;color:#fff;border:0;border-radius:8px;padding:9px 12px;margin:4px 2px}button.alt{background:#71827d}button:disabled{opacity:.45;cursor:not-allowed}input{width:70px;padding:8px}.muted{color:#64756f}.error{color:#a32828}</style><header><b>CityManager Market · SANDBOX</b><span id=guest></span></header><main><div class=notice>This UI uses fake credits and the explicit fake catalog wood/stone/iron. Real saves, city deposits/withdrawals, payments, and production claims are disabled.</div><div id=offline class="notice error" hidden>Offline. Market mutations are disabled; reconnect to retry an unresolved request.</div><section id=login class=card><h2>Guest entry</h2><p>Resume a valid browser guest session, or explicitly create a new isolated guest.</p><button id=enter>Enter as guest</button><p id=msg class=muted></p></section><section id=app hidden><div class=grid><div class=card><h2>Wallet</h2><p id=wallet></p><p id=inv></p><button id=seed class=alt>Seed fake fixture</button><button id=list>List 1 fake wood</button></div><div class=card><h2>Receipts</h2><ul id=receipts></ul></div><div class=card><h2>My listings</h2><ul id=mine></ul></div></div><div class=card><h2>Buy from players</h2><div id=listings class=grid></div></div><div class=card><h2>Wallet history</h2><ul id=ledger></ul></div></section></main><script>const $=x=>document.getElementById(x),pendingKey='market.pending',cookie=n=>document.cookie.split('; ').find(x=>x.startsWith(n+'='))?.slice(n.length+1)||'';let offline=false;function mutateButtons(){document.querySelectorAll('button').forEach(b=>b.disabled=offline)}async function api(p,o={}){if(offline&&o.method&&o.method!=='GET')throw new Error('offline: mutation disabled');const h={...(o.headers||{})};if(o.method&&o.method!=='GET'){h['x-csrf-token']=cookie('cm_csrf');h['content-type']='application/json'}const r=await fetch(p,{...o,headers:h});let b=null;try{b=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(b?.error||'Request failed'),{status:r.status});return b}async function current(){return api('/v1/me')}async function recover(m){const raw=localStorage.getItem(pendingKey);if(!raw)return;const p=JSON.parse(raw);if(p.guest_id&&p.guest_id!==m.guest_id){localStorage.setItem(pendingKey+'.quarantine',raw);localStorage.removeItem(pendingKey);$('msg').textContent='An unresolved buy belongs to an older guest and was quarantined; it was not replayed.';$('msg').className='error';return}const b=document.createElement('button');b.textContent='Retry unresolved buy';b.onclick=async()=>{try{const r=await api('/v1/listings/'+p.id+'/buy',{method:'POST',headers:{'idempotency-key':p.key},body:JSON.stringify({quantity:p.q})});localStorage.removeItem(pendingKey);await api('/v1/receipts/'+r.operation_id+'/ack',{method:'POST'});b.remove();refresh()}catch(e){$('msg').textContent='Response uncertain; same request remains pending. '+e.message;$('msg').className='error'}};$('msg').replaceChildren(document.createTextNode('Unresolved purchase response. '),b)}async function refresh(){try{const [m,i,l,my,r,w]=await Promise.all([current(),api('/v1/inventory'),api('/v1/listings'),api('/v1/my/listings'),api('/v1/receipts'),api('/v1/wallet/ledger')]);$('guest').textContent=' · '+m.guest_id.slice(0,8);$('wallet').textContent='Credits: '+m.balance;$('inv').textContent='Fake stock: '+i.items.map(x=>x.item_code+' '+x.quantity).join(', ');$('listings').replaceChildren(...l.map(x=>{const d=document.createElement('div');d.className='card';const p=document.createElement('p');p.textContent=x.item_code+' · '+x.unit_price+' credits · '+x.quantity+' available';const q=document.createElement('input');q.type='number';q.min=1;q.max=x.quantity;q.value=1;const b=document.createElement('button');b.textContent='Buy';b.onclick=()=>buy(x.id,Number(q.value));d.append(p,q,b);return d}));$('mine').replaceChildren(...my.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+x.status;if(x.status==='open'){const b=document.createElement('button');b.textContent='Cancel';b.className='alt';b.onclick=()=>cancel(x.id);li.append(' ',b)}return li}));$('receipts').replaceChildren(...r.map(x=>{const li=document.createElement('li');li.textContent=x.item_code+' × '+x.quantity+' · '+(x.acknowledged_at?'acknowledged':'pending');if(!x.acknowledged_at){const b=document.createElement('button');b.textContent='Retry';b.onclick=()=>retry(x.operation_id);li.append(' ',b)}return li}));$('ledger').replaceChildren(...w.map(x=>{const li=document.createElement('li');li.textContent=x.kind+' '+x.amount+' credits';return li}));mutateButtons()}catch(e){$('msg').textContent=e.message;$('msg').className='error';if(!navigator.onLine){offline=true;$('offline').hidden=false;mutateButtons()}}}async function enter(){try{const m=await current();$('login').hidden=true;$('app').hidden=false;await recover(m);await refresh()}catch(e){if(e.status===401){try{const m=await api('/v1/auth/guest',{method:'POST',body:'{}'});$('login').hidden=true;$('app').hidden=false;await recover(m);await refresh()}catch(x){$('msg').textContent=x.message;$('msg').className='error'}}else{$('msg').textContent=e.message;$('msg').className='error'}}}async function buy(id,q){const existing=localStorage.getItem(pendingKey);if(existing){$('msg').textContent='Resolve the existing pending purchase before starting another.';$('msg').className='error';return}const m=await current(),key=crypto.randomUUID();localStorage.setItem(pendingKey,JSON.stringify({guest_id:m.guest_id,id,q,key}));try{const r=await api('/v1/listings/'+id+'/buy',{method:'POST',headers:{'idempotency-key':key},body:JSON.stringify({quantity:q})});localStorage.removeItem(pendingKey);await api('/v1/receipts/'+r.operation_id+'/ack',{method:'POST'});refresh()}catch(e){$('msg').textContent='Response uncertain; retry the same request after reconnect. '+e.message;$('msg').className='error'}}async function retry(op){try{await api('/v1/receipts/'+op+'/retry',{method:'POST'});await api('/v1/receipts/'+op+'/ack',{method:'POST'});refresh()}catch(e){$('msg').textContent=e.message;$('msg').className='error'}}async function cancel(id){try{await api('/v1/listings/'+id+'/cancel',{method:'POST'});refresh()}catch(e){$('msg').textContent=e.message;$('msg').className='error'}}$('enter').onclick=enter;$('seed').onclick=()=>api('/v1/sandbox/fixture',{method:'POST'}).then(refresh).catch(e=>{$('msg').textContent=e.message});$('list').onclick=()=>api('/v1/listings',{method:'POST',body:JSON.stringify({item_code:'wood',unit_price:25,quantity:1})}).then(refresh).catch(e=>{$('msg').textContent=e.message});addEventListener('offline',()=>{offline=true;$('offline').hidden=false;mutateButtons()});addEventListener('online',()=>{offline=false;$('offline').hidden=true;mutateButtons();refresh()});</script>`;
